local KTool = CS.Engine.Lib.KTool
------------ import ------------
local CommonPlayerHeadNode = "Game.Behaviours.CommonPlayerHeadNode"
local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
--- from: Assets/BundleResources/Prefabs/Thanksgiving/ThanksgivingRankingsDialog121301.prefab
---@class CompetePlayerRankingNode
