local CompetePlayerRankingNode = Class('CompetePlayerRankingNode')

function CompetePlayerRankingNode:__init()
    self._data = nil
    self._isMe = false                     --是否是自己
    self._commonPlayerHeadNodeScr = nil
    self.comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CompeteComponent)
end

function CompetePlayerRankingNode:__delete()
    self._data = nil
    self._isMe = nil
    self._commonPlayerHeadNodeScr = nil
    self.comp = nil
end

function CompetePlayerRankingNode:Awake()
    if not self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
    end
end

---Refresh
---@param data table 
---@param isMe boolean 是否是自己 
function CompetePlayerRankingNode:Refresh(data, isMe, scale)
    if not data then
        return
    end
    self._data = data
    self._isMe = isMe
    self._scale = scale
    self:FillOtherInfo()
end

--绘制别人的
function CompetePlayerRankingNode:FillOtherInfo()
    CfUtils.FillText(self.TxtDamage, checkNumber(self._data.score))
    CfUtils.FillText(self.Txtranking, checkNumber(self._data.rankNum))
    CfUtils.FillText(self.TextLevel, "Lv."..checkNumber(self._data.level))

    local status = checkNumber(self._data.rankNum) > 4 and 5 or checkNumber(self._data.rankNum)
    CfUtils.SetUISwitchText(self.Txtranking, status)
    CfUtils.SetUISwitchImage(self.ImgRank, status)
    CfUtils.SetUISwitchImage(self.controller.gameObject.transform:Find("ImgRank2"), status)

    CfUtils.FillImage(self.ImageBg, CfUtils.GetRankListBg(checkNumber(self._data.rankNum)), false)
    local playerInfo = self._data
    if playerInfo then
        if self._commonPlayerHeadNodeScr then
            self._commonPlayerHeadNodeScr:FreshAvatarFrame(playerInfo.avatar, playerInfo.avatarFrame)
        end
        CfUtils.SetScale(self.CommonPlayerHeadNode, (checkNumber(self._data.rankNum) > 3) and Vector3(0.3, 0.3, 1) or Vector3(0.4, 0.4, 1))
        CfUtils.FillText(self.TxtName, playerInfo.name)

        local playerDojo = playerComp:GetPlayerDojo()
        KTool.SetActive(self.ImgMyself, (checkNumber(playerInfo.playerId) == checkNumber(playerDojo.playerId)))
    end
end
function CompetePlayerRankingNode:FillPercentageRank(rankData)
    local num = rankData.rankNum
    num = checkNumber(num)
    CfUtils.SetActive(self.ItileRank.transform:Find("NotEnterNode"), num > 0)
    if num <= 0 then
        local rankNum = tostring(rankData.rankNum)
        CfUtils.SetActive(self.ItileRank.transform:Find("NotEnterNode"), true)
        if rankNum  == "0" then
            local TxtRanking3 = self.ItileRank.transform:Find("NotEnterNode/TxtRanking3")
            if not isNull(TxtRanking3) then
                CfUtils.SetActive(TxtRanking3, true)
            end
        else
            local TxtRanking2 = self.ItileRank.transform:Find("NotEnterNode/TxtRanking2")
            if not isNull(TxtRanking2) then
                CfUtils.SetActive(self.BtnDetails, true)
            end
            CfUtils.SetActive(TxtRanking2, true)
            CfUtils.FillText(TxtRanking2,  rankNum)
        end
    end
    CfUtils.SetActive(self.Txtranking, num > 0)
    CfUtils.SetActive(self.ImgRank, num > 0)
end

function CompetePlayerRankingNode:GetRankVo(num)
    local t = self.comp:GetCompeteRankRewards()
    if not t then
        return nil
    end
    for k, v in pairs(t) do
        if checkNumber(v.type) == 2 then
            if num >= checkNumber(v.upperLimit) and num <= checkNumber(v.lowerLimit) then
                return v
            end
        end
    end
    return nil
end

function CompetePlayerRankingNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return CompetePlayerRankingNode
